hold_ticks := 0
if ((#Porch_ContactSensor).contactSensor_contact == false) {
hold_ticks = hold_ticks + 1
    if (hold_ticks >= 60) {
(#Porch_Light).switch_on()
        delay(3 MIN)
(#Porch_Light).switch_off()
        break
}
}
else {
hold_ticks = 0
}

